import { describe, expect, test } from "bun:test";
import { validateJson } from "./validate-json";

describe("validateJson", () => {
  test("returns success for valid JSON object", () => {
    const result = validateJson('{"name": "test"}');
    expect(result.valid).toBe(true);
    expect(result.error).toBeUndefined();
  });

  test("returns success for valid JSON array", () => {
    const result = validateJson('[1, 2, 3]');
    expect(result.valid).toBe(true);
    expect(result.error).toBeUndefined();
  });

  test("returns success for valid JSON primitives", () => {
    expect(validateJson('"string"').valid).toBe(true);
    expect(validateJson('123').valid).toBe(true);
    expect(validateJson('true').valid).toBe(true);
    expect(validateJson('null').valid).toBe(true);
  });

  test("returns error for invalid JSON syntax", () => {
    const result = validateJson('{invalid}');
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("returns error for empty input", () => {
    const result = validateJson('');
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("returns error for whitespace-only input", () => {
    const result = validateJson('   \n\t  ');
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("returns success for complex nested JSON", () => {
    const complexJson = JSON.stringify({
      user: { name: "Alice", age: 30 },
      items: [{ id: 1 }, { id: 2 }],
      active: true
    });
    const result = validateJson(complexJson);
    expect(result.valid).toBe(true);
  });

  test("returns error for trailing comma", () => {
    const result = validateJson('{"key": "value",}');
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });
});

#!/usr/bin/env bun

export interface ValidationResult {
  valid: boolean;
  error?: string;
}

export function validateJson(input: string): ValidationResult {
  const trimmed = input.trim();

  if (trimmed.length === 0) {
    return {
      valid: false,
      error: "Empty input: no JSON data provided"
    };
  }

  try {
    JSON.parse(trimmed);
    return { valid: true };
  } catch (err) {
    const errorMessage = err instanceof Error ? err.message : "Unknown error";
    return {
      valid: false,
      error: `Invalid JSON: ${errorMessage}`
    };
  }
}

async function readStdin(): Promise<string> {
  const chunks: Uint8Array[] = [];

  for await (const chunk of process.stdin) {
    chunks.push(chunk);
  }

  const buffer = Buffer.concat(chunks);
  return buffer.toString('utf-8');
}

async function main(): Promise<void> {
  try {
    const input = await readStdin();
    const result = validateJson(input);

    if (result.valid) {
      console.log("✓ Valid JSON");
      process.exit(0);
    } else {
      console.error(`✗ ${result.error}`);
      process.exit(1);
    }
  } catch (err) {
    const errorMessage = err instanceof Error ? err.message : "Unknown error";
    console.error(`✗ Error: ${errorMessage}`);
    process.exit(1);
  }
}

if (import.meta.main) {
  main();
}

