/**
 * Utility functions for the eval test project.
 */

/**
 * Greeting style options for the greet function.
 */
export type GreetingStyle = "default" | "formal" | "casual" | "morning" | "afternoon" | "evening";

/**
 * Options for customizing greeting behavior.
 */
export interface GreetOptions {
  /**
   * The style of greeting to use.
   * - "default": Standard hello greeting
   * - "formal": Formal business greeting
   * - "casual": Informal friendly greeting
   * - "morning": Time-specific morning greeting
   * - "afternoon": Time-specific afternoon greeting
   * - "evening": Time-specific evening greeting
   */
  style?: GreetingStyle;
}

/**
 * Greet someone by name with optional styling.
 *
 * @param name - The name of the person to greet
 * @param options - Optional greeting customization options
 * @returns A formatted greeting string
 *
 * @example
 * ```ts
 * greet("Alice")                          // "Hello, Alice!"
 * greet("Alice", { style: "formal" })     // "Good day, Alice."
 * greet("Alice", { style: "casual" })     // "Hey, Alice!"
 * greet("Alice", { style: "morning" })    // "Good morning, Alice!"
 * ```
 */
export function greet(name: string, options?: GreetOptions): string {
  const style = options?.style ?? "default";

  switch (style) {
    case "formal":
      return `Good day, ${name}.`;
    case "casual":
      return `Hey, ${name}!`;
    case "morning":
      return `Good morning, ${name}!`;
    case "afternoon":
      return `Good afternoon, ${name}!`;
    case "evening":
      return `Good evening, ${name}!`;
    case "default":
    default:
      return `Hello, ${name}!`;
  }
}

