/**
 * High-performance JSON validator using Bun's native capabilities.
 */

export interface ValidationResult {
  valid: boolean;
  error?: string;
  data?: unknown;
}

export interface SchemaRule {
  type?: 'string' | 'number' | 'boolean' | 'object' | 'array' | 'null';
  required?: boolean;
  properties?: Record<string, SchemaRule>;
  items?: SchemaRule;
}

/**
 * Validates JSON string and returns parsed data if valid.
 */
export function validateJson(input: string): ValidationResult {
  try {
    const data = JSON.parse(input);
    return { valid: true, data };
  } catch (error) {
    return {
      valid: false,
      error: error instanceof Error ? error.message : 'Invalid JSON',
    };
  }
}

/**
 * Validates data against a schema definition.
 */
export function validateSchema(data: unknown, schema: SchemaRule): ValidationResult {
  if (schema.type) {
    const actualType = Array.isArray(data) ? 'array' : data === null ? 'null' : typeof data;

    if (actualType !== schema.type) {
      return {
        valid: false,
        error: `Type mismatch: expected ${schema.type}, got ${actualType}`,
      };
    }
  }

  if (schema.type === 'object' && schema.properties && typeof data === 'object' && data !== null && !Array.isArray(data)) {
    const obj = data as Record<string, unknown>;

    for (const [key, rule] of Object.entries(schema.properties)) {
      if (rule.required && !(key in obj)) {
        return {
          valid: false,
          error: `Missing required property: ${key}`,
        };
      }

      if (key in obj) {
        const result = validateSchema(obj[key], rule);
        if (!result.valid) {
          return {
            valid: false,
            error: `Property '${key}': ${result.error}`,
          };
        }
      }
    }
  }

  if (schema.type === 'array' && schema.items && Array.isArray(data)) {
    for (let i = 0; i < data.length; i++) {
      const result = validateSchema(data[i], schema.items);
      if (!result.valid) {
        return {
          valid: false,
          error: `Array item ${i}: ${result.error}`,
        };
      }
    }
  }

  return { valid: true, data };
}

/**
 * Validates JSON string against a schema in a single operation.
 */
export function validateJsonWithSchema(input: string, schema: SchemaRule): ValidationResult {
  const parseResult = validateJson(input);
  if (!parseResult.valid) {
    return parseResult;
  }

  return validateSchema(parseResult.data, schema);
}

import { describe, expect, test } from "bun:test";
import { validateJson, validateSchema, validateJsonWithSchema, type SchemaRule } from "./json-validator";

describe("validateJson", () => {
  test("parses valid JSON string", () => {
    const result = validateJson('{"name": "Alice", "age": 30}');
    expect(result.valid).toBe(true);
    expect(result.data).toEqual({ name: "Alice", age: 30 });
    expect(result.error).toBeUndefined();
  });

  test("parses valid JSON array", () => {
    const result = validateJson('[1, 2, 3, "test"]');
    expect(result.valid).toBe(true);
    expect(result.data).toEqual([1, 2, 3, "test"]);
  });

  test("parses JSON primitives", () => {
    expect(validateJson('"string"').valid).toBe(true);
    expect(validateJson('123').valid).toBe(true);
    expect(validateJson('true').valid).toBe(true);
    expect(validateJson('null').valid).toBe(true);
  });

  test("rejects invalid JSON", () => {
    const result = validateJson('{invalid json}');
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
    expect(result.data).toBeUndefined();
  });

  test("rejects malformed JSON with trailing comma", () => {
    const result = validateJson('{"key": "value",}');
    expect(result.valid).toBe(false);
  });

  test("rejects incomplete JSON", () => {
    const result = validateJson('{"key":');
    expect(result.valid).toBe(false);
  });

  test("handles empty object", () => {
    const result = validateJson('{}');
    expect(result.valid).toBe(true);
    expect(result.data).toEqual({});
  });

  test("handles empty array", () => {
    const result = validateJson('[]');
    expect(result.valid).toBe(true);
    expect(result.data).toEqual([]);
  });
});

describe("validateSchema", () => {
  test("validates string type", () => {
    const schema: SchemaRule = { type: 'string' };
    expect(validateSchema("hello", schema).valid).toBe(true);
    expect(validateSchema(123, schema).valid).toBe(false);
  });

  test("validates number type", () => {
    const schema: SchemaRule = { type: 'number' };
    expect(validateSchema(123, schema).valid).toBe(true);
    expect(validateSchema("123", schema).valid).toBe(false);
  });

  test("validates boolean type", () => {
    const schema: SchemaRule = { type: 'boolean' };
    expect(validateSchema(true, schema).valid).toBe(true);
    expect(validateSchema(false, schema).valid).toBe(true);
    expect(validateSchema(1, schema).valid).toBe(false);
  });

  test("validates null type", () => {
    const schema: SchemaRule = { type: 'null' };
    expect(validateSchema(null, schema).valid).toBe(true);
    expect(validateSchema(undefined, schema).valid).toBe(false);
  });

  test("validates array type", () => {
    const schema: SchemaRule = { type: 'array' };
    expect(validateSchema([1, 2, 3], schema).valid).toBe(true);
    expect(validateSchema({}, schema).valid).toBe(false);
  });

  test("validates object type", () => {
    const schema: SchemaRule = { type: 'object' };
    expect(validateSchema({}, schema).valid).toBe(true);
    expect(validateSchema([], schema).valid).toBe(false);
  });

  test("validates object with required properties", () => {
    const schema: SchemaRule = {
      type: 'object',
      properties: {
        name: { type: 'string', required: true },
        age: { type: 'number', required: true },
      },
    };

    expect(validateSchema({ name: "Alice", age: 30 }, schema).valid).toBe(true);
    expect(validateSchema({ name: "Alice" }, schema).valid).toBe(false);
    expect(validateSchema({ age: 30 }, schema).valid).toBe(false);
  });

  test("validates nested object properties", () => {
    const schema: SchemaRule = {
      type: 'object',
      properties: {
        user: {
          type: 'object',
          required: true,
          properties: {
            id: { type: 'number', required: true },
            name: { type: 'string', required: true },
          },
        },
      },
    };

    const valid = { user: { id: 1, name: "Alice" } };
    const invalid = { user: { id: "1", name: "Alice" } };

    expect(validateSchema(valid, schema).valid).toBe(true);
    expect(validateSchema(invalid, schema).valid).toBe(false);
  });

  test("validates array items", () => {
    const schema: SchemaRule = {
      type: 'array',
      items: { type: 'number' },
    };

    expect(validateSchema([1, 2, 3], schema).valid).toBe(true);
    expect(validateSchema([1, "2", 3], schema).valid).toBe(false);
  });

  test("validates array of objects", () => {
    const schema: SchemaRule = {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'number', required: true },
        },
      },
    };

    expect(validateSchema([{ id: 1 }, { id: 2 }], schema).valid).toBe(true);
    expect(validateSchema([{ id: 1 }, { name: "test" }], schema).valid).toBe(false);
  });

  test("allows optional properties", () => {
    const schema: SchemaRule = {
      type: 'object',
      properties: {
        name: { type: 'string', required: true },
        email: { type: 'string', required: false },
      },
    };

    expect(validateSchema({ name: "Alice" }, schema).valid).toBe(true);
    expect(validateSchema({ name: "Alice", email: "alice@example.com" }, schema).valid).toBe(true);
  });

  test("provides descriptive error messages", () => {
    const schema: SchemaRule = { type: 'string' };
    const result = validateSchema(123, schema);
    expect(result.error).toContain("expected string");
    expect(result.error).toContain("got number");
  });
});

describe("validateJsonWithSchema", () => {
  test("validates valid JSON against schema", () => {
    const schema: SchemaRule = {
      type: 'object',
      properties: {
        name: { type: 'string', required: true },
        age: { type: 'number', required: true },
      },
    };

    const result = validateJsonWithSchema('{"name": "Alice", "age": 30}', schema);
    expect(result.valid).toBe(true);
  });

  test("rejects invalid JSON before schema validation", () => {
    const schema: SchemaRule = { type: 'object' };
    const result = validateJsonWithSchema('{invalid}', schema);
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("rejects valid JSON that fails schema", () => {
    const schema: SchemaRule = {
      type: 'object',
      properties: {
        age: { type: 'number', required: true },
      },
    };

    const result = validateJsonWithSchema('{"age": "30"}', schema);
    expect(result.valid).toBe(false);
    expect(result.error).toContain("Type mismatch");
  });

  test("handles complex nested schema", () => {
    const schema: SchemaRule = {
      type: 'object',
      properties: {
        users: {
          type: 'array',
          required: true,
          items: {
            type: 'object',
            properties: {
              id: { type: 'number', required: true },
              name: { type: 'string', required: true },
              active: { type: 'boolean', required: true },
            },
          },
        },
      },
    };

    const validJson = JSON.stringify({
      users: [
        { id: 1, name: "Alice", active: true },
        { id: 2, name: "Bob", active: false },
      ],
    });

    expect(validateJsonWithSchema(validJson, schema).valid).toBe(true);
  });
});

describe("performance benchmarks", () => {
  test("validates large JSON object efficiently", () => {
    const largeObject: Record<string, unknown> = {};
    for (let i = 0; i < 1000; i++) {
      largeObject[`key${i}`] = `value${i}`;
    }
    const json = JSON.stringify(largeObject);

    const start = performance.now();
    const result = validateJson(json);
    const duration = performance.now() - start;

    expect(result.valid).toBe(true);
    expect(duration).toBeLessThan(10);
  });

  test("validates large array efficiently", () => {
    const largeArray = Array.from({ length: 10000 }, (_, i) => i);
    const json = JSON.stringify(largeArray);

    const start = performance.now();
    const result = validateJson(json);
    const duration = performance.now() - start;

    expect(result.valid).toBe(true);
    expect(duration).toBeLessThan(20);
  });

  test("schema validation with many properties is efficient", () => {
    const schema: SchemaRule = {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'number', required: true },
          name: { type: 'string', required: true },
        },
      },
    };

    const data = Array.from({ length: 1000 }, (_, i) => ({
      id: i,
      name: `user${i}`,
    }));

    const start = performance.now();
    const result = validateSchema(data, schema);
    const duration = performance.now() - start;

    expect(result.valid).toBe(true);
    expect(duration).toBeLessThan(50);
  });

  test("early bailout on invalid JSON is fast", () => {
    const invalidJson = '{' + 'a'.repeat(10000);

    const start = performance.now();
    const result = validateJson(invalidJson);
    const duration = performance.now() - start;

    expect(result.valid).toBe(false);
    expect(duration).toBeLessThan(5);
  });
});

#!/usr/bin/env bun

/**
 * CLI tool for JSON validation.
 * Usage: bun src/cli-validate-json.ts <file.json> [schema.json]
 */

import { validateJson, validateJsonWithSchema, type SchemaRule } from "./json-validator";

async function main() {
  const args = process.argv.slice(2);

  if (args.length === 0) {
    console.error("Usage: bun src/cli-validate-json.ts <file.json> [schema.json]");
    console.error("\nExamples:");
    console.error("  bun src/cli-validate-json.ts data.json");
    console.error("  bun src/cli-validate-json.ts data.json schema.json");
    process.exit(1);
  }

  const jsonPath = args[0];
  const schemaPath = args[1];

  try {
    const jsonFile = Bun.file(jsonPath);
    const jsonContent = await jsonFile.text();

    if (!schemaPath) {
      const result = validateJson(jsonContent);

      if (result.valid) {
        console.log("✓ Valid JSON");
        console.log(JSON.stringify(result.data, null, 2));
        process.exit(0);
      } else {
        console.error("✗ Invalid JSON");
        console.error(`Error: ${result.error}`);
        process.exit(1);
      }
    } else {
      const schemaFile = Bun.file(schemaPath);
      const schemaContent = await schemaFile.text();
      const schemaResult = validateJson(schemaContent);

      if (!schemaResult.valid) {
        console.error("✗ Invalid schema file");
        console.error(`Error: ${schemaResult.error}`);
        process.exit(1);
      }

      const schema = schemaResult.data as SchemaRule;
      const result = validateJsonWithSchema(jsonContent, schema);

      if (result.valid) {
        console.log("✓ Valid JSON (matches schema)");
        console.log(JSON.stringify(result.data, null, 2));
        process.exit(0);
      } else {
        console.error("✗ JSON validation failed");
        console.error(`Error: ${result.error}`);
        process.exit(1);
      }
    }
  } catch (error) {
    console.error("✗ Error reading file");
    console.error(error instanceof Error ? error.message : "Unknown error");
    process.exit(1);
  }
}

