/**
 * High-performance JSON validator using Bun's native capabilities.
 */

export interface ValidationResult {
  valid: boolean;
  error?: string;
  data?: unknown;
}

export interface SchemaRule {
  type?: 'string' | 'number' | 'boolean' | 'object' | 'array' | 'null';
  required?: boolean;
  properties?: Record<string, SchemaRule>;
  items?: SchemaRule;
}

/**
 * Validates JSON string and returns parsed data if valid.
 */
export function validateJson(input: string): ValidationResult {
  try {
    const data = JSON.parse(input);
    return { valid: true, data };
  } catch (error) {
    return {
      valid: false,
      error: error instanceof Error ? error.message : 'Invalid JSON',
    };
  }
}

/**
 * Validates data against a schema definition.
 */
export function validateSchema(data: unknown, schema: SchemaRule): ValidationResult {
  if (schema.type) {
    const actualType = Array.isArray(data) ? 'array' : data === null ? 'null' : typeof data;

    if (actualType !== schema.type) {
      return {
        valid: false,
        error: `Type mismatch: expected ${schema.type}, got ${actualType}`,
      };
    }
  }

  if (schema.type === 'object' && schema.properties && typeof data === 'object' && data !== null && !Array.isArray(data)) {
    const obj = data as Record<string, unknown>;

    for (const [key, rule] of Object.entries(schema.properties)) {
      if (rule.required && !(key in obj)) {
        return {
          valid: false,
          error: `Missing required property: ${key}`,
        };
      }

      if (key in obj) {
        const result = validateSchema(obj[key], rule);
        if (!result.valid) {
          return {
            valid: false,
            error: `Property '${key}': ${result.error}`,
          };
        }
      }
    }
  }

  if (schema.type === 'array' && schema.items && Array.isArray(data)) {
    for (let i = 0; i < data.length; i++) {
      const result = validateSchema(data[i], schema.items);
      if (!result.valid) {
        return {
          valid: false,
          error: `Array item ${i}: ${result.error}`,
        };
      }
    }
  }

  return { valid: true, data };
}

/**
 * Validates JSON string against a schema in a single operation.
 */
export function validateJsonWithSchema(input: string, schema: SchemaRule): ValidationResult {
  const parseResult = validateJson(input);
  if (!parseResult.valid) {
    return parseResult;
  }

  return validateSchema(parseResult.data, schema);
}

import { describe, expect, test } from "bun:test";
import { validateJson, validateSchema, validateJsonWithSchema, type SchemaRule } from "./json-validator";

describe("validateJson", () => {
  test("parses valid JSON string", () => {
    const result = validateJson('{"name": "Alice", "age": 30}');
    expect(result.valid).toBe(true);
    expect(result.data).toEqual({ name: "Alice", age: 30 });
    expect(result.error).toBeUndefined();
  });

  test("parses valid JSON array", () => {
    const result = validateJson('[1, 2, 3, "test"]');
    expect(result.valid).toBe(true);
    expect(result.data).toEqual([1, 2, 3, "test"]);
  });

  test("parses JSON primitives", () => {
    expect(validateJson('"string"').valid).toBe(true);
