#!/usr/bin/env bun

/**
 * CLI tool for JSON validation.
 * Usage: bun src/cli-validate-json.ts <file.json> [schema.json]
 */

import { validateJson, validateJsonWithSchema, type SchemaRule } from "./json-validator";

async function main() {
  const args = process.argv.slice(2);

  if (args.length === 0) {
    console.error("Usage: bun src/cli-validate-json.ts <file.json> [schema.json]");
    console.error("\nExamples:");
    console.error("  bun src/cli-validate-json.ts data.json");
    console.error("  bun src/cli-validate-json.ts data.json schema.json");
    process.exit(1);
  }

  const jsonPath = args[0];
  const schemaPath = args[1];

  try {
    const jsonFile = Bun.file(jsonPath);
    const jsonContent = await jsonFile.text();

    if (!schemaPath) {
      const result = validateJson(jsonContent);

      if (result.valid) {
        console.log("✓ Valid JSON");
        console.log(JSON.stringify(result.data, null, 2));
        process.exit(0);
      } else {
        console.error("✗ Invalid JSON");
        console.error(`Error: ${result.error}`);
        process.exit(1);
      }
    } else {
      const schemaFile = Bun.file(schemaPath);
      const schemaContent = await schemaFile.text();
      const schemaResult = validateJson(schemaContent);

      if (!schemaResult.valid) {
        console.error("✗ Invalid schema file");
        console.error(`Error: ${schemaResult.error}`);
        process.exit(1);
      }

      const schema = schemaResult.data as SchemaRule;
      const result = validateJsonWithSchema(jsonContent, schema);

      if (result.valid) {
        console.log("✓ Valid JSON (matches schema)");
        console.log(JSON.stringify(result.data, null, 2));
        process.exit(0);
      } else {
        console.error("✗ JSON validation failed");
        console.error(`Error: ${result.error}`);
        process.exit(1);
      }
    }
  } catch (error) {
    console.error("✗ Error reading file");
    console.error(error instanceof Error ? error.message : "Unknown error");
    process.exit(1);
  }
}

main();

