     4→
     5→export interface ValidationResult {
     6→  valid: boolean;
     7→  error?: string;
     8→  data?: unknown;
     9→}
    10→
    11→export interface SchemaRule {
    12→  type?: 'string' | 'number' | 'boolean' | 'object' | 'array' | 'null';
    13→  required?: boolean;
    14→  properties?: Record<string, SchemaRule>;
    15→  items?: SchemaRule;
    16→}
    17→
    18→/**
    19→ * Validates JSON string and returns parsed data if valid.
    20→ */
    21→export function validateJson(input: string): ValidationResult {
    22→  try {
    23→    const data = JSON.parse(input);
    24→    return { valid: true, data };
    25→  } catch (error) {
    26→    return {
    27→      valid: false,
    28→      error: error instanceof Error ? error.message : 'Invalid JSON',
    29→    };
    30→  }
    31→}
    32→
    33→/**
    34→ * Validates data against a schema definition.
    35→ */
    36→export function validateSchema(data: unknown, schema: SchemaRule): ValidationResult {
    37→  if (schema.type) {
    38→    const actualType = Array.isArray(data) ? 'array' : data === null ? 'null' : typeof data;
    39→
    40→    if (actualType !== schema.type) {
    41→      return {
    42→        valid: false,
    43→        error: `Type mismatch: expected ${schema.type}, got ${actualType}`,
    44→      };
    45→    }
    46→  }
    47→
    48→  if (schema.type === 'object' && schema.properties && typeof data === 'object' && data !== null && !Array.isArray(data)) {
    49→    const obj = data as Record<string, unknown>;
    50→
    51→    for (const [key, rule] of Object.entries(schema.properties)) {
    52→      if (rule.required && !(key in obj)) {
    53→        return {
    54→          valid: false,
    55→          error: `Missing required property: ${key}`,
    56→        };
    57→      }
    58→
    59→      if (key in obj) {
    60→        const result = validateSchema(obj[key], rule);
    61→        if (!result.valid) {
    62→          return {
    63→            valid: false,
    64→            error: `Property '${key}': ${result.error}`,
    65→          };
    66→        }
    67→      }
    68→    }
    69→  }
    70→
    71→  if (schema.type === 'array' && schema.items && Array.isArray(data)) {
    72→    for (let i = 0; i < data.length; i++) {
    73→      const result = validateSchema(data[i], schema.items);
    74→      if (!result.valid) {
    75→        return {
    76→          valid: false,
    77→          error: `Array item ${i}: ${result.error}`,
    78→        };
    79→      }
    80→    }
    81→  }
    82→
    83→  return { valid: true, data };
    84→}
    85→
    86→/**
    87→ * Validates JSON string against a schema in a single operation.
    88→ */
    89→export function validateJsonWithSchema(input: string, schema: SchemaRule): ValidationResult {
    90→  const parseResult = validateJson(input);
    91→  if (!parseResult.valid) {
    92→    return parseResult;
    93→  }
    94→
    95→  return validateSchema(parseResult.data, schema);
    96→}
